package th.co.scgroup1989.scpda;
import org.json.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.net.*;import java.io.*;
// Calls the shipping Java session against an explicitly isolated loopback server.
public final class NativeDailyHarness {
 static final class Device implements StockDaySession.DeviceProof {
 final KeyPair pair;final String id;String cert="",daily="";final Path file;
 Device(String path)throws Exception{file=Paths.get(path);if(Files.exists(file)){JSONObject s=new JSONObject(new String(Files.readAllBytes(file),StandardCharsets.UTF_8));KeyFactory k=KeyFactory.getInstance("EC");pair=new KeyPair(k.generatePublic(new java.security.spec.X509EncodedKeySpec(Base64.getDecoder().decode(s.getString("pub")))),k.generatePrivate(new java.security.spec.PKCS8EncodedKeySpec(Base64.getDecoder().decode(s.getString("key")))));id=s.getString("id");cert=s.optString("cert");daily=s.optString("daily");}else{KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));pair=g.generateKeyPair();id=UUID.randomUUID().toString();save();}}
 void save(){try{Files.write(file,new JSONObject().put("id",id).put("pub",Base64.getEncoder().encodeToString(pair.getPublic().getEncoded())).put("key",Base64.getEncoder().encodeToString(pair.getPrivate().getEncoded())).put("cert",cert).put("daily",daily).toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}}
 public String publicKey(){return Base64.getEncoder().encodeToString(pair.getPublic().getEncoded());}public String deviceId(){return id;}public String certificate(){return cert;}public void saveCertificate(String c){cert=c;save();}public String dailySessionId(){return daily;}public void saveDailySessionId(String s){daily=s;save();}public String sign(String text)throws Exception{Signature s=Signature.getInstance("SHA256withECDSA");s.initSign(pair.getPrivate());s.update(text.getBytes(StandardCharsets.UTF_8));return Base64.getEncoder().encodeToString(s.sign());}}
 static final class Wire implements StockDaySession.Wire{public StockDaySession.Reply send(String method,String path,JSONObject body,Map<String,String> headers,CookieManager ignored)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:39817"+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(5000);c.setReadTimeout(10000);for(Map.Entry<String,String> h:headers.entrySet())c.setRequestProperty(h.getKey(),h.getValue());if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();try(InputStream in=status>=400?c.getErrorStream():c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new StockDaySession.Reply(status,new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8)));}finally{c.disconnect();}}}
 public static void main(String[] args)throws Exception{if(args.length<3||args.length>6)throw new Exception("Use synthetic invitation, JPEG and output paths");String user=args.length>3?args[3]:"01005";int version=args.length>4?Integer.parseInt(args[4]):17;Device d=new Device(args[2]+".synthetic-device.json");StockDaySession api=new StockDaySession(new Wire(),d,version);api.activate(new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8)));String image="data:image/jpeg;base64,"+Base64.getEncoder().encodeToString(Files.readAllBytes(Paths.get(args[1])));JSONObject me=api.execute("login",new JSONObject().put("username",user).put("password","fixturePassword").put("selfie",image));if(!me.optBoolean("dailySession")||!me.optBoolean("countUploadAvailable"))throw new Exception("Daily primary login/count failed");StockDaySession reopened=new StockDaySession(new Wire(),d,version);if(!reopened.execute("status",new JSONObject()).optBoolean("dailyResumeAvailable"))throw new Exception("Resume marker missing");if(!reopened.execute("resume",new JSONObject()).getJSONObject("user").getString("operatorCode").equals(user))throw new Exception("Resume identity mismatch");JSONObject qr=reopened.execute("createCompanionQr",args.length>5?new JSONObject().put("target",args[5]):new JSONObject());Files.write(Paths.get(args[2]),qr.toString().getBytes(StandardCharsets.UTF_8));System.out.println("Shipping JVM primary login, count capability, reopen/proof resume, actual-version QR passed (synthetic only)");}
}
